<script setup lang="ts">
import InputText from 'primevue/inputtext'
import Password from 'primevue/password'
import Button from 'primevue/button'
import Message from 'primevue/message'

definePageMeta({ layout: false })
useSeoMeta({ title: 'Admin Login | Alumni Portal', robots: 'noindex, nofollow' })

const supabase = useSupabaseClient()
const user = useSupabaseUser()
const { appName } = useSiteConfig()

watch(user, (newUser) => {
  if (newUser) navigateTo('/admin/dashboard')
}, { immediate: true })

const email = ref('')
const password = ref('')
const loading = ref(false)
const error = ref('')

async function handleLogin() {
  if (!email.value || !password.value) {
    error.value = 'Please enter email and password'
    return
  }

  loading.value = true
  error.value = ''

  try {
    const { error: authError } = await supabase.auth.signInWithPassword({
      email: email.value,
      password: password.value,
    })

    if (authError) {
      error.value = authError.message.includes('Invalid login credentials')
        ? 'Invalid email or password'
        : authError.message
      return
    }

    // Verify admin_users record exists
    const { data: adminData } = await supabase
      .from('admin_users')
      .select('id, is_active')
      .eq('email', email.value)
      .single()

    if (!adminData || !adminData.is_active) {
      await supabase.auth.signOut()
      error.value = 'You do not have admin access'
      return
    }

    navigateTo('/admin/dashboard')
  }
  catch (e: any) {
    error.value = e.message || 'Login failed'
  }
  finally {
    loading.value = false
  }
}
</script>

<template>
  <div class="min-h-screen flex items-center justify-center bg-gradient-to-br from-slate-900 via-slate-800 to-primary-900 p-4">
    <div class="w-full max-w-md">
      <div class="text-center mb-8">
        <NuxtLink to="/" class="inline-flex items-center gap-3">
          <div class="flex h-12 w-12 items-center justify-center rounded-xl bg-primary-500 text-white text-xl font-bold shadow-lg">
            A
          </div>
          <div class="text-left">
            <h1 class="text-xl font-bold text-white">{{ appName }}</h1>
            <p class="text-sm text-slate-400">Admin Panel</p>
          </div>
        </NuxtLink>
      </div>

      <div class="bg-white rounded-2xl shadow-2xl p-8">
        <h2 class="text-2xl font-bold text-slate-900 text-center mb-2">Admin Login</h2>
        <p class="text-slate-500 text-center mb-6">Sign in to manage the alumni portal</p>

        <Message v-if="error" severity="error" class="mb-4" :closable="false">
          {{ error }}
        </Message>

        <form class="space-y-5" @submit.prevent="handleLogin">
          <div>
            <label class="block text-sm font-medium text-slate-700 mb-1.5">Email</label>
            <InputText v-model="email" type="email" placeholder="admin@example.com" class="w-full" :disabled="loading" />
          </div>
          <div>
            <label class="block text-sm font-medium text-slate-700 mb-1.5">Password</label>
            <Password v-model="password" placeholder="Password" :feedback="false" toggle-mask class="w-full" input-class="w-full" :disabled="loading" />
          </div>
          <Button type="submit" label="Sign In" icon="pi pi-sign-in" class="w-full" :loading="loading" />
        </form>

        <div class="mt-6 text-center">
          <NuxtLink to="/" class="text-sm text-slate-400 hover:text-primary-600 transition-colors inline-flex items-center gap-1">
            <i class="pi pi-arrow-left text-xs" />
            Back to site
          </NuxtLink>
        </div>
      </div>
    </div>
  </div>
</template>
